-- Applied to production after progressive-challenge.sql.
-- Requires the private gte-small embedding worker. Backfill missing active clue,
-- tier-witness, and new association vectors using semantic_seed_words before
-- activating the verified pool. This snapshot reflects production validation,
-- not a replacement for running validation after a model change.

-- 20261125010548 ascent_independent_clue_matching_and_typo_correction
create extension if not exists fuzzystrmatch with schema extensions;
create table ascent_game.spelling_vocabulary(word text primary key);
alter table ascent_game.spelling_vocabulary enable row level security;
revoke all on ascent_game.spelling_vocabulary from public,anon,authenticated;
insert into ascent_game.spelling_vocabulary(word)
select distinct word from (select word from ascent_game.association_scores_v7 union select clue from ascent_game.association_scores_v7 union select alias from ascent_game.answer_aliases_v7 union select canonical from ascent_game.answer_aliases_v7) q where word ~ '^[a-z]+( [a-z]+){0,5}$' on conflict do nothing;
-- Protect correctly spelled common words even when they have no association in the game.
insert into ascent_game.spelling_vocabulary(word) select unnest(string_to_array('about above across actual after again against almost along already also always among another answer around away back before being below between both bring build business called came case cause change close come common could course cover create daily dance death deep different does done down draw drive early earth eight either empty enough even every example face fact family far fast feel field find first five floor follow food form four free friend front full game gave general give good great group grow hand hard have head hear help here high hold home hope hour house human idea image into just keep kind know land large last late lead learn left less life light like line list little live long look lose love made main make many mean measure might mind more most move much music name near need never next night none note number often once only open order other over page part past path people place plan play point power press price print put quick quite read real right road room round rule same save school score second see seem sentence set short show side since small some song sound space stand start state still stop store such take talk team tell term test than that them then there these thing think those three through time today together tone took top total town train true turn under until used very voice walk want warm water way week well went were what when where which while white whole will wind with word work world would write wrong year young yours',' ')) on conflict do nothing;
create function ascent_game.correct_spelling(raw text) returns text language plpgsql stable set search_path='' as $fn$
declare normalized text; limit_edits int; best text; dist int; second_dist int; n int;
begin
 normalized:=lower(btrim(regexp_replace(regexp_replace(coalesce(raw,''),'[’'']','','g'),'[[:space:]‐‑–—-]+',' ','g')));
 normalized:=btrim(regexp_replace(normalized,'[.!?]+$','','g'));
 if normalized !~ '^[a-z]+( [a-z]+){0,5}$' or length(normalized)<5 or length(normalized)>65 then return normalized;end if;
 if exists(select 1 from ascent_game.spelling_vocabulary where word=normalized) or exists(select 1 from ascent_game.association_scores_v7 where word=normalized or clue=normalized) then return normalized;end if;
 if not exists(select 1 from unnest(string_to_array(normalized,' ')) t where not exists(select 1 from ascent_game.spelling_vocabulary where word=t)) then return normalized;end if;
 limit_edits:=case when length(normalized)>=10 then 2 else 1 end;
 with candidates as (
 select word,case when length(word)=length(normalized) and exists(select 1 from generate_series(1,length(normalized)-1) i where word=substr(normalized,1,i-1)||substr(normalized,i+1,1)||substr(normalized,i,1)||substr(normalized,i+2)) then 1 else extensions.levenshtein_less_equal(normalized,word,limit_edits) end d
 from ascent_game.spelling_vocabulary where abs(length(word)-length(normalized))<=limit_edits and cardinality(string_to_array(word,' '))=cardinality(string_to_array(normalized,' ')) and left(word,1)=left(normalized,1)
 ), ranked as (select word,d from candidates where d<=limit_edits order by d,word limit 2)
 select (array_agg(word order by d,word))[1],(array_agg(d order by d,word))[1],(array_agg(d order by d,word))[2] into best,dist,second_dist from ranked;
 if best is not null and (second_dist is null or second_dist>dist) then return best;end if;
 return normalized;
end;$fn$;
revoke all on function ascent_game.correct_spelling(text) from public,anon,authenticated;
-- Check each clue independently, with corroboration from an existing association.
create function ascent_game.vector_clue_matches(clues text[],guess text,g extensions.vector(384)) returns jsonb language sql stable set search_path='' as $fn$
 with evidence as (
 select s.clue,s.word,s.reason,1-(a.embedding operator(extensions.<=>) g) similarity,1-(c.embedding operator(extensions.<=>) g) direct,
 cardinality(string_to_array(s.word,' '))=cardinality(string_to_array(guess,' ')) same_size
 from ascent_game.association_scores_v7 s join ascent_game.semantic_word_vectors a on a.word=s.word join ascent_game.semantic_word_vectors c on c.word=s.clue
 where s.clue=any(clues) and s.word<>all(clues) and s.strength>=78 and s.reason not like 'Semantic link via %'
 ), graded as (
 select *,count(*) filter(where similarity>=.89) over(partition by clue) supporting
 from evidence
 ), best as (
 select distinct on(clue) clue,word,reason,similarity,direct from graded
 where (same_size and similarity>=.925 and direct>=.79) or (similarity>=.91 and direct>=.85 and supporting>=2) or (direct>=.90 and similarity>=.86)
 order by clue,similarity desc,word
 )
 select coalesce(jsonb_object_agg(clue,'Semantic match via “'||word||'” — '||reason||' ('||round(similarity*100)::int||'% similarity)'),'{}') from best
$fn$;
revoke all on function ascent_game.vector_clue_matches(text[],text,extensions.vector) from public,anon,authenticated;
do $patch$ declare d text;n text;begin
select pg_get_functiondef('ascent_game.semantic_fallback(text[],text,uuid)'::regprocedure) into d;
n:=substring(d from 1 for position(' -- A close alternative' in d)-1)||' return ascent_game.vector_clue_matches(clues,clean_guess,g); exception when others then return ''{}''::jsonb; end;$function$';
if position(' -- A close alternative' in d)=0 then raise exception 'Semantic fallback patch mismatch';end if;
execute n;
end;$patch$;
create or replace function ascent_game.semantic_complete_guess(clues text[],guess text,ticket uuid,known jsonb) returns jsonb language plpgsql volatile set search_path='' as $fn$
declare normalized text; corrected text; missing text[]; more jsonb;
begin
 normalized:=lower(btrim(regexp_replace(regexp_replace(coalesce(guess,''),'[’'']','','g'),'[[:space:]‐‑–—-]+',' ','g')));
 normalized:=btrim(regexp_replace(normalized,'[.!?]+$','','g'));
 if normalized=any(clues) or (select count(*) from jsonb_object_keys(known))=cardinality(clues) then return known;end if;
 if known='{}'::jsonb then
  corrected:=ascent_game.correct_spelling(normalized);
  if corrected<>normalized and corrected<>all(clues) then
   known:=ascent_game.match_guess(7,clues,corrected);
   if known<>'{}'::jsonb then
    select jsonb_object_agg(key,'Interpreted as “'||corrected||'” — '||value) into known from jsonb_each_text(known);
    return known;
   end if;
  end if;
 end if;
 missing:=array(select c from unnest(clues) c where not known ? c);
 if cardinality(missing)=0 then return known;end if;
 more:=ascent_game.semantic_fallback(missing,normalized,ticket);
 return known||coalesce(more,'{}'::jsonb);
exception when others then return known;
end;$fn$;

-- 20261125010618 ascent_conservative_typo_safeguards
insert into ascent_game.spelling_vocabulary select distinct t from ascent_game.spelling_vocabulary v cross join lateral unnest(string_to_array(v.word,' ')) t where length(t)>1 on conflict do nothing;
insert into ascent_game.spelling_vocabulary select unnest(array['banana','musical','performer','carpet','physics','quantum','tailoring','seamstress','clothes','clothing','sewing','washing','piano','violin','guitar','instrument','musician','planet','animal','vegetable','fruit','fish','bird','dog','cat','apple','orange','pear','bear','beet','bead','beach','bench','peach','pearl','plain','plane','trail','trial','train','brain','grain','rain','pain','paint','plant','flour','flower','flourish','flesh','flash','flood','floor','blood','blond','blonde','moral','mural','mortar','motor','meter','metre','metal','medal','model','modal','motel','hotel','hostel','horse','house','mouse','moose','mousse','loose','lose','chose','choose','close','cloth','clothe','clothes','clove','glove','globe','grove','groove','groom','broom','bloom','bread','breed','broad','board','beard','heard','heart','hearth','earth','heath','heather']) on conflict do nothing;
do $patch$ declare d text;n text;begin
select pg_get_functiondef('ascent_game.semantic_complete_guess(text[],text,uuid,jsonb)'::regprocedure) into d;
n:=replace(d,'if corrected<>normalized and corrected<>all(clues) then','if corrected<>normalized and corrected=any(clues) then return known;end if;
  if corrected<>normalized then');
n:=replace(n,'more:=ascent_game.semantic_fallback(missing,normalized,ticket);','more:=ascent_game.semantic_fallback(missing,coalesce(corrected,normalized),ticket);');
if n=d then raise exception 'Correction patch mismatch';end if;execute n;
end;$patch$;


