-- 20261125010931 ascent_validate_expanded_semantic_scoring
create function ascent_game.preview_registered_guess(clues text[],guess text) returns jsonb language sql stable set search_path='' as $fn$
 with base as (select ascent_game.match_guess(7,clues,guess) known), v as (select embedding from ascent_game.semantic_word_vectors where word=guess)
 select known||coalesce((select ascent_game.vector_clue_matches(array(select c from unnest(clues) c where not known ? c),guess,embedding) from v where (select enabled from ascent_game.semantic_config where singleton)), '{}'::jsonb) from base
$fn$;
revoke all on function ascent_game.preview_registered_guess(text[],text) from public,anon,authenticated;
-- Add spelling vocabulary tokens for all recent additions.
insert into ascent_game.spelling_vocabulary select distinct t from ascent_game.additional_associations_v7 v cross join lateral unnest(string_to_array(v.word,' ')) t where length(t)>1 on conflict do nothing;

-- 20261125011342 ascent_semantic_validated_board_flag
alter table ascent_game.rich_tier_boards_v7 add column if not exists semantic_verified boolean not null default false;

-- 20261125011503 ascent_use_semantic_verified_challenge_pool
do $patch$ declare d text;n text;begin
 select pg_get_functiondef('ascent_game.generate_varied_climb(text,uuid)'::regprocedure) into d;
 n:=replace(d,'where b.difficulty_grade>0 and b.target<>all(used_targets)','where b.semantic_verified and b.difficulty_grade>0 and b.target<>all(used_targets)');
 n:=replace(n,'(b.phrase_count<>required_phrases),(case when i>=2 then b.difficulty_grade<>2 else false end),(select count(*) from unnest(b.clues) c where c=any(prior_clues)),coalesce(u.n,0)','(b.phrase_count<>required_phrases),coalesce(u.n,0),(case when i>=2 then b.quality<920 else false end),(case when i>=2 then b.difficulty_grade<>2 else false end),(select count(*) from unnest(b.clues) c where c=any(prior_clues))');
 n:=replace(n,'ascent_game.match_guess(7,candidate.clues,w.word)','ascent_game.preview_registered_guess(candidate.clues,w.word)');
 if n=d or n not like '%b.semantic_verified%' or n not like '%b.quality<920%' or n not like '%preview_registered_guess(candidate.clues,w.word)%' then raise exception 'Generator patch mismatch';end if;
 execute n;
end;$patch$;
-- Review scored candidates using the same cached semantic matcher, and include validated tier witnesses.
create or replace function public.ascent_top_answers(p_ticket uuid,p_day date,p_archive date default null,p_seed uuid default null,p_pitch integer default 1)
returns jsonb language sql stable security definer set search_path='' as $fn$
with board as (
 select c.lex_version,array(select jsonb_array_elements_text(c.boards->(p_pitch-1)->'clues')) clues
 from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when p_seed is null then 'daily:'||to_char(r.day,'YYYY-MM-DD') else 'practice:'||p_seed end
 where r.ticket=p_ticket and r.day=p_day and jsonb_array_length(r.history)=5
 and r.scope=case when p_seed is not null then 'practice:'||p_seed when p_archive=p_day then 'replay' else 'daily' end and p_pitch between 1 and 5
), raw as (
 select e.key word,count(*)::int hits,jsonb_object_agg(e.clue,e.value) links,b.clues,b.lex_version
 from board b cross join lateral (
 select l.clue,e.key,e.value from ascent_game.circuit_lexicon l cross join lateral jsonb_each_text(l.links) e where l.edition=b.lex_version and b.lex_version<>7 and l.clue=any(b.clues)
 union all select s.clue,s.word,s.reason||' ('||s.strength||'% match)' from ascent_game.association_scores_v7 s where b.lex_version=7 and s.clue=any(b.clues) and s.strength>=65
 ) e where e.key<>all(b.clues) group by e.key,b.clues,b.lex_version
), raw_ranked as (
 select *,row_number() over(partition by hits order by length(word),word collate "C") rn from raw
), witnesses as (
 select distinct w.word from board b join ascent_game.rich_tier_boards_v7 r on b.clues @> r.clues and r.clues @> b.clues and r.semantic_verified
 cross join lateral jsonb_array_elements(r.tier_witnesses) t(words) cross join lateral jsonb_array_elements_text(t.words) w(word)
), evaluated as materialized (
 select word,clues,case when lex_version=7 then ascent_game.preview_registered_guess(clues,word) else links end links
 from raw_ranked where lex_version<>7 or rn<=30 or word in(select word from witnesses)
), matched as (
 select *, (select count(*)::int from jsonb_object_keys(links)) hits from evaluated
), ranked as (
 select word,hits,links,case when hits=6 then 200 else 10*(hits*(hits+1)/2+(select count(*) from generate_series(1,3) i where links ? clues[i] and links ? clues[i+3])) end points from matched where hits>0
), tier_ranked as (
 select *,row_number() over(partition by hits order by points desc,word collate "C") tier_rank from ranked
), chosen as (
 select * from tier_ranked order by (tier_rank<=case hits when 1 then 10 when 2 then 5 when 3 then 4 when 4 then 5 when 5 then 3 else 1 end) desc,points desc,word collate "C" limit 100
)
select coalesce(jsonb_agg(jsonb_build_object('word',word,'hits',hits,'links',links,'points',points) order by points desc,word collate "C"),'[]') from chosen;
$fn$;

-- 20261125011533 ascent_correct_common_typos_and_complete_corrected_guesses
create table ascent_game.spelling_exceptions(word text primary key, corrected text not null);
alter table ascent_game.spelling_exceptions enable row level security;
revoke all on ascent_game.spelling_exceptions from public,anon,authenticated;
insert into ascent_game.spelling_exceptions values ('musican','musician'),('muscian','musician'),('musiciann','musician'),('violen','violin'),('viollin','violin'),('clohtes','clothes'),('clohing','clothing'),('seewing','sewing'),('seiwng','sewing'),('dentst','dentist'),('dentisit','dentist'),('detergant','detergent'),('laundrey','laundry'),('guitarr','guitar'),('guiter','guitar'),('orcestra','orchestra'),('orchetra','orchestra'),('reciept','receipt'),('recipt','receipt'),('envlope','envelope'),('enveloppe','envelope'),('writting','writing'),('writen','written'),('buisness','business'),('bussiness','business'),('beleive','believe'),('seperate','separate'),('freind','friend'),('bananna','banana'),('bannana','banana'),('eletricity','electricity'),('electrcity','electricity'),('tecnology','technology'),('technolgy','technology'),('communcation','communication'),('commuication','communication'),('comunication','communication'),('medecine','medicine'),('medicne','medicine'),('artisit','artist'),('artst','artist'),('vehical','vehicle'),('vechicle','vehicle'),('measurment','measurement'),('mesurement','measurement'),('restaraunt','restaurant'),('restuarant','restaurant'),('enviroment','environment');
do $patch$ declare d text;n text;begin
select pg_get_functiondef('ascent_game.correct_spelling(text)'::regprocedure) into d;
n:=replace(d,'if not exists(select 1 from unnest(string_to_array(normalized,'' '')) t','select corrected into best from ascent_game.spelling_exceptions where word=normalized; if best is not null then return best;end if;
 if not exists(select 1 from unnest(string_to_array(normalized,'' '')) t');
if n=d then raise exception 'Spelling exception patch mismatch';end if;execute n;end;$patch$;
